using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class LudovicoAriosto
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "chi fa sua vendetta, oltra che offende | chi offeso l'ha, da molti si difende.", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Piccola è questa casa, ma sufficiente per me, nessuno vi ha ragioni sopra, è pulita, infine è stata fatta con i miei denari.", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Né che poco io vi dia da imputar sono, | che quanto io possa dar, tutto vi dono.", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Ecco il giudicio uman come spesso erra!", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Oh gran bontà de' cavalieri antiqui!", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Pel bosco Ferraú molto s'avvolse,| e ritrovossi al fine onde si tolse.", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Né tempo avendo a pensar altra scusa, | e conoscendo ben che 'l ver gli disse, | restò senza risposta a bocca chiusa", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "La verginella è simile alla rosa | Ch'in bel giardin su la nativa spina | Mentre sola e sicura si riposa, | Né gregge né pastor se le avvicina: | L'aura soave e l'alba rugiadosa, | L'acqua, la terra al suo favor s'inchina: | Gioveni vaghi e donne innamorate | Amano averne e seni e tempie ornate", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Che chi ne l'acqua sta fin alla gola | ben è ostinato se mercé non grida.", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Forse era ver, ma non però credibile, | a chi del senso suo fosse signore; | ma parve facilmente a lui possibile, | ch'era perduto in via più grave errore. | Quel che l'uom vede, Amor gli fa invisibile, | e l'invisibil fa vedere Amore. | Questo creduto fu; che 'l miser suole | dar facile credenza a quel che vuole.", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Corro la fresca e matutina rosa | Che tardando stagion perder potria", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Ingiustissimo amor, perché sì raro | corrispondenti fai nostri desiri? ... da chi disia il mio amor tu mi richiami, | e chi m'ha in odio vuoi ch'adori ed ami.", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Questo disir, ch'a tutti sta nel core, | de' fatti altrui sempre cercar novella...", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Ma ne li vizi abominandi e brutti | non pur gli altri adeguò, ma passò tutti.", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Quantunque il simular sia le più volte | ripreso, e dia di mala mente indici, | si trova pur in molte cose e molte | aver fatti evidenti benefici, | e danni e biasmi e morti aver già tolte; | che non conversiam sempre con gli amici | in questa assai più oscura che serena | vita mortal, tutta d'invidia piena.", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Perché si de' punir donna o biasmare, | che con uno o più d'uno abbia commesso | quel che l'uom fa con quante n'ha appetito, | e lodato ne va, non che impunito?", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Tutti gli altri animai che sono in terra, | o che vivon quïeti e stanno in pace, | o se vengono a rissa e si fan guerra, | alla femina il maschio non la face: | l'orsa con l'orso al bosco sicura erra, | la leonessa appresso il leon giace; | col lupo vive la lupa sicura, | né la iuvenca ha del torel paura. || Ch'abominevol peste, che Megera | è venuta a turbar gli umani petti? | che si sente il marito e la mogliera | sempre garrir d'ingiuriosi detti, | stracciar la faccia e far livida e nera, | bagnar di pianto i genïali letti; | e non di pianto sol, ma alcuna volta | di sangue gli ha bagnati l'ira stolta. || Parmi non sol gran mal, ma che l'uom faccia | contra natura e sia di Dio ribello, | che s'induce a percuotere la faccia | di bella donna, o romperle un capello: | ma chi le dà veneno, o chi le caccia | l'alma del corpo con laccio o coltello, | ch'uomo sia quel non crederò in eterno, | ma in vista umana un spirto de l'inferno.", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Ben s'ode il ragionar, si vede il volto: | Ma dentro il petto mal giudicar puossi", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Oh Dio, che disse e fece, poi che sola | si ritrovò nel suo fidato letto! | percosse il seno, e si stracciò la stola, | e fece all'aureo crin danno e dispetto.", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Miser chi mal oprando si confida | Ch'ognor star debbia il maleficio occulto; | Che quando ogn'altro taccia, intorno grida | L'aria e la terra istessa in ch'è sepulto: | E Dio fa spesso che 'l peccato guida | Il peccator, poi ch'alcun dì gli ha indulto, | Che sé medesmo, senza altrui richiesta, | Inavvedutamente manifesta", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Come aviene a un disperato spesso, | che da lontan brama e disia la morte, | e l'odia poi che se la vede appresso, | tanto gli pare il passo acerbo e forte", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Pareami aver qui tutto il ben raccolto | che fra i mortali in piú parti si smembra, | a chi piú et a chi meno e a nessun molto", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Donna sì laida, che la terra tutta | né la più vecchia avea né la più brutta", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Ho perduto l'onor, ch'è stato peggio; | che, se ben con effetto io non peccai, | io do però materia ch'ognun dica, | ch'essendo vagabonda, io sia impudica", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Non comincia Fortuna mai per poco, | quando un mortal si piglia a scherno e a gioco", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Ben ch'esser donna sia in tutte le bande | danno e sciagura, quivi era pur grande", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Io credea e credo, e creder credo il vero", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "L'amante, per aver quel che desia, | senza guardar che Dio tutto ode e vede, | aviluppa promesse e giuramenti, | che tutti spargon poi per l'aria i venti", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Bene è felice quel, donne mie care, | ch'essere accorto all'altrui spese impare", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Che fossi fatto in quarti, arso o impiccato, | brutto ladron, villan, superbo, ingrato", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Natura il fece, e poi ruppe la stampa", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Che ben fu il più crudele e il più di quanti | mai furo al mondo ingegni empi e maligni, | ch'imaginò sì abominosi ordigni", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "E spenta ogni pietà, strage nefanda | di quel popul facean per tutti i liti: | fosse iustizia, o fosse crudeltade, | né sesso riguardavano né etade", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Dirò insomma, ch'in lei dal capo al piede, | quant'esser può beltà, tutta si vede", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "A tutti par che quella cosa sia, | che piú ciascun per sé brama e desia", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Avea piacevol viso, abito onesto, | un umil volger d'occhi, un andar grave, | un parlar sì benigno e sì modesto, | che parea Gabriel che dicesse: Ave. | Era brutta e deforme in tutto il resto: | ma nascondea queste fattezze prave | con lungo abito e largo; e sotto quello, | attosicato avea sempre il coltello", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Fu il vincer sempre mai laudabil cosa | Vincasi o per fortuna o per ingegno", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "O d'ogni vizio fetida sentina, | dormi, Italia imbriaca, e non ti pesa | ch'ora di questa gente, ora di quella | che già serva ti fu, sei fatta ancella?", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Che l'uomo il suo destin fugge di raro", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "non è il ribaldo questo, | che si fa laude con l'altrui buone opre? | e la virtú di chi non è ben desto, | con la sua infamia e col suo obbrobrio copre?", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Che sarebbe pensier non troppo accorto | perder duo vivi per salvare un morto", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Alcun non può saper da chi sia amato | quando felice in su la ruota siede; | però c'ha i veri e i finti amici a lato, | che mostran tutti una medesma fede. | Se poi si cangia in tristo il lieto stato, | volta la turba adulatrice il piede; | e quel che di cor ama, riman forte, | et ama il suo Signor dopo la morte", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Se, come il viso, si mostrasse il core", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Le donne son venute in eccellenza | di ciascun'arte ove hanno posto cura", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Che non è soma da portar sí grave, | come aver donna, quando a noia s'have", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Credo che t'abbia la Natura e Dio | produtto, o scelerato sesso, al mondo | per una soma, per un grave fio | de l'uom, che senza te saria giocondo", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "A donna non si fa maggior dispetto, | che quando o vecchia o brutta le vien detto", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Il consiglio del mal va raro invano", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Amor, con che miracolo lo fai, | che 'n fuoco li tenghi, e nol consumi mai?", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Chi mette il piè su l'amorosa pania, | cerchi ritrarlo, e non v'inveschi l'ale; | che non è in somma amor, se non insania, | a giudizio de' savi universale: | e se ben come Orlando ognun non smania, | suo furor mostra a qualch'altro segnale. | E quale è di pazzia segno più espresso | che, per altri voler, perder sé stesso? | Vari gli effetti son, ma la pazzia | è tutt'una però, che li fa uscire. | Gli è come una gran selva, ove la via | conviene a forza, a chi va, fallire: | chi su, chi giù, chi qua, chi là travia. | Per concludere in somma, io vi vo' dire: | a chi in amor s'invecchia, oltr'ogni pena, | si convengono i ceppi e la catena", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Senza il pane discerner da le giande, | dal digiuno e da l'impeto cacciato, | le mani e il dente lasciò andar di botto | in quel che trovò prima, o crudo o cotto", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "L'animo è pronto, ma il potere è zoppo", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Di più direi; ma di men dir bisogna", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Io sua non son, né d'altri son che mia: | dunque me tolga a me chi mi desia", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Gli è teco cortesia l'esser villano", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Non siate però tumide e fastose, | donne, per dir che l'uom sia vostro figlio; | che de le spine ancor nascon le rose, | e d'una fetida erba nasce il giglio", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Mettendolo Turpino, anch'io l'ho messo", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Se piú che crini avesse occhi il marito, | non potria far che non fosse tradito.", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Non conosce la pace e non l'estima | chi provato non ha la guerra prima.", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Vide gran copia di panie con visco, | ch'erano, o donne, le bellezze vostre", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Altri in amar lo [il senno] perde, altri in onori, | altri in cercar, scorrendo il mar, richezze; | altri ne le speranze de' signori, | altri dietro alle magiche sciocchezze; | altri in gemme, altri in opre di pittori, | et altri in altro che piú d'altro aprezze", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Del re de' fiumi tra l'altiere corna | or siede umile (diceagli) e piccol borgo: | dinanzi il Po, di dietro gli soggiorna | d'alta palude un nebuloso gorgo; | che, volgendosi gli anni, la più adorna | di tutte le città d'Italia scorgo, | non pur di mura e d'ampli tetti regi, | ma di bei studi e di costumi egregi", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "voglion tutti gli ordini e le leggi, | Che chi dà morte altrui, debb'esser morto.", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Che s'abbia a ritrovar con numer pare | Di cavallieri armati in Lipadusa. | Una isoletta è questa, che dal mare | Medesmo che li cinge, è circonfusa.", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Temerità per certo e pazzia vera | è la tua, e di qualunque che si pose | a consigliar mai cosa buona o ria, | ove chiamato a consigliar non sia", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Che con l'armata avendo la riviera | Di Barberia trascorsa in ogni canto, | Capitò quivi, e l'isola sì fiera, | Montuosa e inegual ritrovò tanto, | Che non è, dice, in tutto il luogo strano, | Ove un sol piè si possa metter piano", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "L'incarco de le corna, e lo più lieve | Ch'al mondo sia, se ben l'huom tanto inſama | Lo vede quasi tutta l'altra gente | E chi l'ha in capo mai non se lo sente", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Ove femine son, son liti e risse", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Bestemmiando fuggì l'alma sdegnosa | Che fu sì altiera al mondo e sì orgogliosa", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "E levar questa donna anco ti voglio; ché sarebbe a lasciartela gran fallo.", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "E quel che non si sa non si de' dire, | e tanto men, quando altri n'ha a patire", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Ma 'l popolo facea, come i più fanno, | ch'ubbidiscon più a quei che più in odio hanno.", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Natura il fece, e poi ruppe la stampa", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "O città bene avventurosa... | ...la gloria tua salirà tanto | ch'avrai di tutta Italia il pregio e 'l vanto", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Or che s'aspetta? Soccorrer qui, non lacrimare accade", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Pazzo chi al suo signor contradir vole, | se ben dicesse c'ha veduto il giorno | pieno di stelle e a mezzanotte il sole", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Più tosto che arricchir, voglio quïete", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "più tosto ch'esser servo | torrò la povertade in pazïenza", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Non si adatta una sella o un basto solo | ad ogni dosso; ad un non par che l'abbia, | all'altro stringe e preme e gli dà duolo", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "In casa mia mi sa meglio una rapa | ch'io cuoca, e cotta s'un stecco me inforco | e mondo, e spargo poi di acetto e sapa, | che all'altrui mensa tordo, starna o porco | selvaggio; e così sotto una vil coltre, | come di seta o d'oro, ben mi corco.", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Degli uomini son varii li appetiti: | a chi piace la chierca, a chi la spada, | a chi la patria, a chi li strani liti", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "Chi vuole andare a torno, a torno vada: | vegga Inghelterra, Ongheria, Francia e Spagna; | a me piace abitar la mia contrada", Author = "Ludovico Ariosto" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Ludovico_Ariosto", Text = "la terra, | senza mai pagar l'oste, andrò cercando | con Ptolomeo, sia il mondo in pace o in guerra; || e tutto il mar, senza far voti quando | lampeggi il ciel, sicuro in su le carte | verrò, più che sui legni, volteggiando", Author = "Ludovico Ariosto" },
        };
    }
}